@import url(&#39;https://fonts.googleapis.com/css2?family=Sora:wght@100;200;300;400;500;600;700;800&amp;display=swap&#39;);
.roeid-button {
    display: inline-block;
    position: relative;
    padding: 0;
    color: #fff;
    font-family: &quot;Sora&quot;, HelveticaNeue, Helvetica Neue, Helvetica, Arial, Lucida Grande, sans-serif;
    font-weight: 600;
    line-height: 1em;
    text-decoration: none;
    border: 0;
    text-align: center;
    cursor: pointer;
    overflow: hidden;
  
}
.roeid-button-icon,
.roeid-button-text {
    display: block;
    float: left;
}
.roeid-button-icon {
    margin: 0 -0.4em 0 0;
    padding: 0.6em 0.8em 0.5em;
}
.roeid-button-text {
    padding: 0.95em 1em 0.85em 1em;
    font-size: 1.15em;
    text-align: center;
}
svg {
    width: 1.8em;
    height: 1.8em;
    fill: #fff;
}
.roeid-button-size-s {
    font-size: 10px;
    width: 190px;
	border-radius: 0.5rem;

}
.roeid-button-size-s &gt; span img {
    width: 19px;
    height: 19px;
    border: 0;
}
.roeid-button-size-m {
    font-size: 15px;
    width: 290px;
	border-radius: 0.8rem;
}
.roeid-button-size-m &gt; span img {
    width: 29px;
    height: 29px;
    border: 0;
}
.roeid-button-size-l {
    font-size: 20px;
    width: 390px;
	border-radius: 1rem;
}
.roeid-button-size-l &gt; span img {
    width: 38px;
    height: 38px;
    border: 0;
}
.roeid-button-size-xl {
    font-size: 25px;
    width: 480px;
	border-radius: 1rem;
}
.roeid-button-size-xl &gt; span img {
    width: 47px;
    height: 47px;
    border: 0;
}
.button-roeid {
    background-color: #2e5ae6;
    color: #fff;
}
.button-roeid svg {
    fill: #fff;
}
.button-roeid:hover {
    background-color: #09338a;
    color: #fff;
}
.button-roeid:active {
    background-color: #8298db;
    color: #036;
}

.button-roeid-white {
    background-color: #f1f3f8;
    color: #2e5ae6;
}
.button-roeid-white svg {
    fill: #2e5ae6;
}
.button-roeid-white:hover {
    background-color: #d1d9e8;
    color: #2e5ae6;
}
.button-roeid-white:active {
    background-color: #8298db;
    color: #2e5ae6;
}
 
